public(package) fun handle_collateral_auto_deleverage<MarketType, DebtType, CollateralType>(
    self: &mut Market<MarketType>,
    obligation_id: ID,
    available_repay_coin: Coin<DebtType>,
    coin_decimals_registry: &CoinDecimalsRegistry,
    x_oracle: &XOracle,
    clock: &Clock,
    now: u64,
    ctx: &mut TxContext,
): (Coin<CollateralType>, Coin<DebtType>, u64) {
    let close_factor_bypass_min_value = self.market_config().close_factor_bypass_min_value;

    let collateral = type_name::with_defining_ids<CollateralType>();

    // load the time locked adl params
    let adl_registry = self.adl_registry<MarketType>();
    let timelock = *adl_registry.get_collateral_deleverage(collateral);

    // refresh obligation
    let obligation = self.obligations.borrow_mut(obligation_id);
    assert!(obligation.market_id() == self.id.uid_as_inner(), error::obligation_from_different_market());

    // obtain the emode group
    let emode_group = self.emode_group_registry.borrow_emode_group_mut(obligation.emode_group());

    // make sure the Collateral Type is indeed a collateral, otherwise revert
    let collateral_setting = emode_group.borrow_emode(collateral).collateral();
    // cannot liquidate asset that is not collateral
    assert!(collateral_setting.can_be_collateral(), error::asset_not_collateral());

    let max_liquidation_incentive = collateral_setting.liquidation_incentive();

    // force interest update for the collateral asset
    let asset = self.assets.load_mut_by_type(collateral);
    accrue_interest<MarketType>(collateral, &mut self.reserves, asset.asset_config(), asset.interest_model(), now);

    let total_deposit = self.reserves.load_by_type(collateral).cash_plus_borrows_minus_reserves().floor();
    let collateral_params = timelock.inner();
    collateral_params.ensure_limit_breached(total_deposit);
    let activation_time = timelock.get_secs_since_activation(clock);

    let liquidation_params = LiquidationParams {
        liquidation_ltv_threshold_override: std::option::some(collateral_params.liquidation_ltv(activation_time)),
        // adl liquidation_incentive should not have exceeded non-adl liquidation_incentive
        liquidation_incentive: collateral_params.liquidation_incentive(activation_time).min(max_liquidation_incentive),
        liquidation_revenue_factor: float::zero(),
        close_factor: collateral_params.close_factor(),
        close_factor_bypass_min_value,
    };

    liquidation_inner<MarketType, DebtType, CollateralType>(
        &mut self.id,
        &self.assets,
        emode_group,
        &mut self.reserves,
        obligation,
        &liquidation_params,
        available_repay_coin,
        coin_decimals_registry,
        x_oracle,
        clock,
        now,
        ctx,
    )
}

fun try_stop_collateral_deleverage<MarketType, CollateralType>(id: &mut UID, reserves: &GenericCoinTypeStorage<Reserve<MarketType>>, collateral: TypeName) {
    let total_deposit = reserves.load_by_type(collateral).cash_plus_borrows_minus_reserves().ceil();
    let adl = dynamic_field::borrow_mut<ADLRegistryKey, AutoDeleverageRegistry>(id, ADLRegistryKey {});
    adl.try_stop_collateral_deleverage<CollateralType>(type_name::with_defining_ids<MarketType>(), total_deposit);
}

fun try_stop_borrow_deleverage<MarketType, DebtType>(market_id: &mut UID, emode_group_id: u8, emode_group: &EModeGroup, debt_type: TypeName) {
    let total_borrow = emode_group.borrow_amount(debt_type).floor();
    let adl = dynamic_field::borrow_mut<ADLRegistryKey, AutoDeleverageRegistry>(market_id, ADLRegistryKey {});
    adl.try_stop_borrow_deleverage<DebtType>(type_name::with_defining_ids<MarketType>(), emode_group_id, total_borrow);
}

fun liquidation_inner<MarketType, DebtType, CollateralType>(
    id: &mut UID,

    assets: &GenericCoinTypeStorage<Asset<MarketType>>,
    emode_group: &mut EModeGroup,

    reserves: &mut GenericCoinTypeStorage<Reserve<MarketType>>,

    obligation: &mut Obligation<MarketType>,

        ctx
    );

    // Transfer the liquiated collateral to the sender
    transfer::public_transfer(collateral_balance, ctx.sender());
    transfer::public_transfer(refund, ctx.sender());
}

